package com.friendinneed.robot;import java.util.concurrent.*;import org.slf4j.*;import org.springframework.stereotype.Service;
@Service public class RobotCommandQueue{private static final Logger log=LoggerFactory.getLogger(RobotCommandQueue.class);private final RobotHardware robot;private final RobotProperties props;private final ScheduledExecutorService executor=Executors.newSingleThreadScheduledExecutor();private volatile double targetPan,targetTilt;private volatile long lastCommand;private volatile boolean thermalCutoff;public RobotCommandQueue(RobotHardware r,RobotProperties p){robot=r;props=p;executor.scheduleAtFixedRate(this::flush,0,50,TimeUnit.MILLISECONDS);}public void moveHead(double pan,double tilt){double p=Math.clamp(pan,props.headPanMin(),props.headPanMax()),t=Math.clamp(tilt,props.headTiltMin(),props.headTiltMax());if(p!=pan||t!=tilt)log.warn("Clamped robot head command pan={}, tilt={}",pan,tilt);targetPan=p;targetTilt=t;}public void setLed(String c,String p){robot.setLed(c,p);}private void flush(){if(robot.getTemperature()>70){if(!thermalCutoff)log.error("CRITICAL robot thermal cutoff");thermalCutoff=true;robot.setLed("#ff0000","solid");return;}thermalCutoff=false;if(System.nanoTime()-lastCommand<33_000_000)return;robot.moveHead(targetPan,targetTilt);lastCommand=System.nanoTime();}public boolean thermalCutoff(){return thermalCutoff;}}
